import type { HTMLAttributes, ReactNode, Ref } from 'react';
import { cn } from '../../utils/cn';
import { statusDotVariants, type StatusDotVariantProps } from './status-dot.variants';

export interface StatusDotProps extends Omit<HTMLAttributes<HTMLSpanElement>, 'className' | 'children'>, StatusDotVariantProps {
  className?: string;
  ref?: Ref<HTMLSpanElement>;
  /** Visible text next to the dot. Without it, pass `aria-label` (or keep the dot decorative). */
  label?: ReactNode;
  /** Soft ping animation for live / in-progress states. Off under prefers-reduced-motion. */
  pulse?: boolean;
}

/**
 * Small state indicator: a coloured dot with an optional label. Colour is never the only
 * signal — give it a `label` or an `aria-label` (then it is exposed as role="img").
 */
export function StatusDot({ tone, size, label, pulse = false, className, ...props }: StatusDotProps) {
  const s = statusDotVariants({ tone, size });
  const named = label == null && props['aria-label'] != null;
  return (
    <span
      role={named ? 'img' : undefined}
      aria-hidden={label == null && !named ? true : undefined}
      data-tone={tone ?? 'neutral'}
      className={cn(s.root(), className)}
      {...props}
    >
      <span aria-hidden className={s.dot()}>
        {pulse && <span data-pulse className={s.ping()} />}
      </span>
      {label != null && <span className={s.label()}>{label}</span>}
    </span>
  );
}

export { StatusDot, type StatusDotProps } from './StatusDot';
export { statusDotVariants, type StatusDotVariantProps, type StatusDotTone } from './status-dot.variants';
export { doc as statusDotDoc } from './StatusDot.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const statusDotVariants = tv({
  slots: {
    root: 'inline-flex items-center gap-2 align-middle',
    dot: 'relative inline-flex shrink-0 rounded-full',
    ping: 'absolute inset-0 animate-ping rounded-full opacity-60 motion-reduce:hidden motion-reduce:animate-none',
    label: 'text-[12.5px] leading-5 font-medium text-foreground',
  },
  variants: {
    tone: {
      success: { dot: 'bg-success', ping: 'bg-success' },
      warning: { dot: 'bg-warning', ping: 'bg-warning' },
      destructive: { dot: 'bg-destructive', ping: 'bg-destructive' },
      info: { dot: 'bg-info', ping: 'bg-info' },
      neutral: { dot: 'bg-muted-foreground', ping: 'bg-muted-foreground' },
      primary: { dot: 'bg-primary', ping: 'bg-primary' },
    },
    size: {
      sm: { dot: 'size-1.5', label: 'text-[12px]' },
      md: { dot: 'size-2' },
      lg: { dot: 'size-2.5', label: 'text-[13px]' },
    },
  },
  defaultVariants: { tone: 'neutral', size: 'md' },
});

export type StatusDotVariantProps = VariantProps<typeof statusDotVariants>;
export type StatusDotTone = NonNullable<StatusDotVariantProps['tone']>;

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'StatusDot',
  group: 'Display',
  status: 'beta',
  description: 'State dot with an optional label and a soft pulse for live states (disabled under reduced motion). Tones: success, warning, destructive, info, neutral, primary — generic, with no product-specific states. Without a label it needs an aria-label (exposed as an image) so colour is never the only signal.',
  pattern: 'img (when unlabelled)',
  tokens: ['success', 'warning', 'destructive', 'info', 'muted-foreground', 'primary', 'foreground'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
